// Vector clock implementation
class VectorClock {
  constructor(nodeId, peers) {
    this.nodeId = nodeId;
    this.clock = {};
    // Initialize all known nodes to 0
    [nodeId, ...peers].forEach(id => { this.clock[id] = 0; });
  }

  tick() {
    this.clock[this.nodeId]++;
    return { ...this.clock }; // snapshot to attach to message
  }

  // Merge on message receive: max per entry, then tick self
  receive(receivedClock) {
    for (const [node, time] of Object.entries(receivedClock)) {
      this.clock[node] = Math.max(this.clock[node] || 0, time);
    }
    this.clock[this.nodeId]++; // local event: receive
  }

  // A happened-before B: A[i] <= B[i] for all i, A != B
  static happensBefore(a, b) {
    const allNodes = new Set([...Object.keys(a), ...Object.keys(b)]);
    let strictlyLess = false;
    for (const node of allNodes) {
      const ai = a[node] || 0;
      const bi = b[node] || 0;
      if (ai > bi) return false;    // a is NOT <= b
      if (ai < bi) strictlyLess = true;
    }
    return strictlyLess; // must be strictly less in at least one position
  }

  static concurrent(a, b) {
    return !VectorClock.happensBefore(a, b) &&
           !VectorClock.happensBefore(b, a);
  }
}

// Demo
const nodeA = new VectorClock('A', ['B', 'C']);
const nodeB = new VectorClock('B', ['A', 'C']);

const v1 = nodeA.tick();           // A: {A:1, B:0, C:0}
nodeB.receive(v1);                 // B: {A:1, B:1, C:0}
const v2 = nodeB.tick();           // B: {A:1, B:2, C:0}

console.log(VectorClock.happensBefore(v1, v2)); // true — v1 → v2

const v3 = nodeA.tick();           // A: {A:2, B:0, C:0} (concurrent with v2)
console.log(VectorClock.concurrent(v2, v3));    // true — A:2 concurrent with B:2

// Logical clocks comparison

// LAMPORT CLOCK — single integer per node
//   Rule: on event, L++; on send, include L; on receive, L = max(L, msg_L) + 1
//   Guarantees: A → B  implies  L(A) < L(B)
//   Does NOT guarantee: L(A) < L(B) implies A → B
//   Use: total ordering (logging, distributed tracing, Paxos ballot numbers)

// VECTOR CLOCK — array/map of integers, one per node
//   Guarantees: A → B  iff  VC(A) < VC(B) component-wise
//   Can detect concurrent events (incomparable vectors)
//   Cost: O(N) space and message overhead (N = number of nodes)
//   Use: conflict detection (Riak, DynamoDB version vectors, Git)

// VERSION VECTOR (database variant)
//   Tracks writes seen from each replica, not events
//   Compatible vectors: safe merge (no conflict)
//   Incomparable vectors: conflict detected → trigger resolution

// HYBRID LOGICAL CLOCK (HLC)
//   Format: (wallClock, logicalCounter) — max(physical, received) + logical
//   Preserves physical time ordering, falls back to logical for causality
//   Use: CockroachDB, YugabyteDB — time-travel queries + causal reads

// PRACTICAL SUMMARY:
// Need total order only?       → Lamport clock (cheap)
// Need conflict detection?     → Vector clock (O(N) cost)
// Need time-travel queries?    → Hybrid logical clock
